"""Validates drug catalogue CSV files and generates SQL for Supabase.

Usage:
    uv run python -m app.drugs.importer ../database/seed/drugs_seed.csv --sql ../supabase/seed.sql
"""

import argparse
import sys
from pathlib import Path

from app.drugs.catalog import CatalogError, load_csv
from app.drugs.models import Drug
from app.drugs.normalize import normalize_brand


def _sql_str(value: str | None) -> str:
    if value is None:
        return "null"
    return "'" + value.replace("'", "''") + "'"


def to_sql(drugs: list[Drug]) -> str:
    lines = [
        "-- Generated by app.drugs.importer. Do not edit by hand.",
        "-- To change: edit the CSV in database/seed/ and run the importer again.",
        "",
        "insert into public.drugs",
        "    (brand, strength, generic, form, manufacturer, brand_normalized, source, verified)",
        "values",
    ]
    rows = [
        "    ("
        + ", ".join(
            [
                _sql_str(d.brand),
                _sql_str(d.strength),
                _sql_str(d.generic),
                _sql_str(d.form),
                _sql_str(d.manufacturer),
                _sql_str(normalize_brand(d.brand)),
                _sql_str(d.source),
                "true" if d.verified else "false",
            ]
        )
        + ")"
        for d in drugs
    ]
    lines.append(",\n".join(rows))
    lines.append("on conflict (brand, strength, form) do update set")
    lines.append(
        "    generic = excluded.generic, manufacturer = excluded.manufacturer,\n"
        "    brand_normalized = excluded.brand_normalized, source = excluded.source,\n"
        "    verified = excluded.verified;"
    )
    return "\n".join(lines) + "\n"


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Validate drug CSV files and generate SQL")
    parser.add_argument("csv", type=Path, nargs="+", help="One or more CSV files")
    parser.add_argument("--sql", type=Path, help="Write SQL here (omit to validate only)")
    args = parser.parse_args(argv)

    all_drugs: list[Drug] = []
    failed = False
    for path in args.csv:
        try:
            drugs, report = load_csv(path)
        except (CatalogError, OSError) as e:
            print(f"error: {e}", file=sys.stderr)
            return 2
        print(f"{path.name}: {report.loaded} drugs")
        for d in report.duplicates:
            print(f"  warning: duplicate skipped: {d}")
        for err in report.errors:
            print(f"  error: {err}", file=sys.stderr)
            failed = True
        all_drugs.extend(drugs)

    unverified = sum(1 for d in all_drugs if not d.verified)
    brands = len({normalize_brand(d.brand) for d in all_drugs})
    print(f"Total: {len(all_drugs)} drugs, {brands} brands")
    if unverified:
        print(f"warning: {unverified} entries are unverified; verify them before patient use")

    if failed:
        print("error: SQL not written because of the errors above", file=sys.stderr)
        return 1
    if args.sql:
        args.sql.write_text(to_sql(all_drugs), encoding="utf-8")
        print(f"SQL written to {args.sql}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
